def summarize_ranges(nums: list[int]) -> str:
    if not nums:
        return   
    nums = sorted(set(nums))
    ranges =  i = 0

    while i < len(nums):
        start = nums[i]
        while i + 1 < len(nums) and nums[i] +1 == nums[i + 1]:
            i += 1
        end = nums[i]

        if end - start >= 2:
            ranges.append(f"{start}..{end}")
        elif end - start == 1:
            ranges.append(f"{start},{end}")
        else:
            ranges.append(f"{start}")

        i += 1

    return ",".join(ranges)
